style.css:
@-moz-document domain("roblox.com") {
body {
    background: url("https://mir-s3-cdn-cf.behance.net/projects/404/b2311d194617153.Y3JvcCw5OTcsNzgwLDIwNCw0Ng.png") no-repeat center center fixed !important;
    background-size: cover !important;
  }

  /* Remove os fundos pretos */
  .dark-theme, .light-theme, body {
    background-color: transparent !important;
  }

  /* Deixa todas as seções transparentes */
  div, section, header, footer {
    background-color: transparent !important;
  }
}
